/* Sports review: changes are audited and official publication is an explicit staff action. */
(() => {
 const lang=document.documentElement.lang==='en'?'en':'fr',word=(fr,en)=>lang==='fr'?fr:en,endpoint='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/race-review';
 const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e;};
 const states={provisional:word('Provisoire','Provisional'),under_review:word('En cours d’examen','Under review'),official:word('Officiel','Official')};
 async function api(query='',body){const response=await fetch(endpoint+query,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+sessionStorage.getItem('atx-racing-session'),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok){const errors={results_locked:word('Cette course est déjà validée. Ses résultats sont verrouillés.','This race has been approved. Its results are locked.'),results_import_in_progress:word('Le Collector importe encore les résultats. Attendez la fin de l’import avant validation.','The Collector is still importing results. Wait until the import finishes before approval.'),teams_required:word('Associez chaque pilote WGT à son équipage avant la validation officielle.','Assign every WGT driver to their crew before official validation.'),positions_conflict:word('Corrigez les positions manquantes ou en doublon avant publication.','Correct missing or duplicate positions before publishing.'),results_required:word('Importez les résultats avant publication.','Import results before publishing.'),race_not_finished:word('La course n’a pas encore eu lieu.','The race has not taken place yet.')};throw Error(errors[data.error]||word('Impossible d’enregistrer cette décision. Vérifiez les champs.','Unable to save this decision. Check the fields.'));}if(body){window.ATX_CLEAR_PUBLIC_EVENTS?.();window.ATX_CLEAR_PUBLIC_LEADERBOARDS?.();window.dispatchEvent(new Event('atx-wallet-changed'));}return data;}
 document.addEventListener('atx:admin-render',async()=>{
  const root=document.querySelector('.admin-content');if(!root)return;const panel=el('section',null,'admin-panel race-review-panel');root.append(panel);panel.append(el('h2',word('Validation des résultats','Results validation')),el('p',word('Vérifiez les résultats importés puis validez la course. Après validation, les résultats et les points sont verrouillés et la course disparaît de cette liste.','Check imported results, then approve the race. After approval, results and points are locked and the race leaves this list.'),'profile-note'));
  const status=el('p',null,'form-status');status.setAttribute('role','status');panel.append(status);
  try{
   const data=await api(),select=el('select');select.setAttribute('aria-label',word('Course à valider','Race to review'));for(const e of (data.events||[]).filter(e=>e.result_publication_state!=='official')){const option=el('option',(e['title_'+lang]||e.title_fr)+' · '+states[e.result_publication_state]);option.value=e.id;select.append(option);}panel.append(select);if(!select.options.length){panel.append(el('p',word('Aucun résultat de compétition à valider.','No competition results to review.')));return;}
   const detail=el('div');panel.append(detail);
   async function render(){detail.replaceChildren();const payload=await api('?event='+encodeURIComponent(select.value));const noteFr=el('textarea'),noteEn=el('textarea');noteFr.maxLength=noteEn.maxLength=2000;noteFr.required=noteEn.required=true;
    const label=(text,input,parent=detail)=>{const l=el('label',null,'profile-field');l.append(el('span',text),input);parent.append(l);};label(word('Motif public · français','Public reason · French'),noteFr);label(word('Motif public · anglais','Public reason · English'),noteEn);
    async function save(body,button){if(!noteFr.value.trim()||!noteEn.value.trim()){status.textContent=word('Renseignez le motif dans les deux langues.','Enter the reason in both languages.');return;}button.disabled=true;status.textContent=word('Enregistrement…','Saving…');try{await api('',{eventId:select.value,...body,reasonFr:noteFr.value.trim(),reasonEn:noteEn.value.trim()});const record=(data.events||[]).find(e=>e.id===select.value);if(record){record.result_publication_state=body.action==='publication'?body.state:'under_review';select.selectedOptions[0].textContent=(record['title_'+lang]||record.title_fr)+' · '+states[record.result_publication_state];}if(body.action==='publication'&&body.state==='official'){select.selectedOptions[0]?.remove();detail.replaceChildren();if(select.options.length)await render();else{select.disabled=true;detail.append(el('p',word('Toutes les courses sont validées.','All races have been approved.')));}status.textContent=word('Course validée. Résultats verrouillés.','Race approved. Results locked.');}else{await render();status.textContent=word('Décision enregistrée.','Decision saved.');}}catch(e){status.textContent=e.message;}finally{button.disabled=false;}}
    const state=el('select');state.setAttribute('aria-label',word('Statut des résultats','Results status'));for(const [key,name] of Object.entries(states)){const o=el('option',name);o.value=key;state.append(o);}state.value=(data.events||[]).find(e=>e.id===select.value)?.result_publication_state||'provisional';const publish=el('button',word('Enregistrer le statut','Save results status'),'action');publish.type='button';publish.onclick=()=>save({action:'publication',state:state.value},publish);const approve=el('button',word('Valider et publier les résultats officiels','Approve and publish official results'),'action');approve.type='button';approve.onclick=()=>save({action:'publication',state:'official'},approve);detail.append(approve,state,publish);
    for(const r of payload.results||[]){const row=el('article',null,'review-result-card');const driver=Array.isArray(r.driver)?r.driver[0]:r.driver;row.append(el('h3',driver?.display_name||'ACC'));const pos=el('input'),points=el('input'),finish=el('select');pos.type=points.type='number';pos.min=1;pos.max=999;pos.step=1;pos.value=r.finish_position||'';points.min=0;points.max=1000;points.step='.01';points.value=r.points||0;for(const key of ['classified','dnf','dns','dsq']){const o=el('option',key.toUpperCase());o.value=key;finish.append(o);}finish.value=r.status;label(word('Position','Position'),pos,row);label(word('Points','Points'),points,row);label(word('Résultat','Outcome'),finish,row);const correct=el('button',word('Enregistrer cette correction · sans publier','Save this correction · without publishing'),'pill');correct.type='button';correct.onclick=()=>{if(!pos.checkValidity()||!points.checkValidity()||!points.value){status.textContent=word('Vérifiez la position et les points.','Check position and points.');return;}save({action:'correct',driverId:r.driver_id,position:pos.value?Number(pos.value):null,points:Number(points.value),status:finish.value},correct);};row.append(correct);detail.append(row);}
    const history=el('details');history.append(el('summary',word('Historique des décisions','Decision history')));for(const d of payload.decisions||[]){const row=el('p',(d['reason_'+lang]||d.reason_fr)+' · '+new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Brussels'}).format(new Date(d.created_at)));history.append(row);}detail.append(history);
   }
   select.onchange=()=>render().catch(e=>status.textContent=e.message);await render();
  }catch(e){status.textContent=e.message;}
 });
})();
